#!/usr/bin/env python3
"""Render bench/results/context.jsonl (from context_bench.py) as bench/CONTEXT.md."""
import json, os

ROOT = os.path.dirname(os.path.abspath(__file__))
IN = os.path.join(ROOT, "results", "context.jsonl")
OUT = os.path.join(ROOT, "CONTEXT.md")

recs = [json.loads(l) for l in open(IN) if l.strip()]
q = [r for r in recs if r.get("mode") == "quality"]
s = [r for r in recs if r.get("mode") == "scale"]


def fmt_int(x):
    return f"{x:,.0f}"


out = ["# `context` extension: what it costs and what it buys", ""]
out.append(
    "Generated by `bench/context_bench.py` (driver) and `bench/context_report.py` from "
    "`bench/results/context.jsonl`. The harness is `bench/src/bin/ctxbench.rs`. "
    "Token counts use `glider::ext::context::tokens`, the estimate the extension budgets with "
    "(about one token per four characters of a word, one per symbol)."
)
out.append("")

if q:
    n = q[0]["nodes"]
    out += [
        "## Retrieval quality on a graph with a known answer",
        "",
        f"{n:,} entities in communities of 50. Each entity links to 5 members of its own community, to 2 random "
        "entities anywhere (noise) and to one of 10 hubs; every edge has the same type, so only structure separates "
        "signal from noise. From a random seed, the relevant context is the seed's community. "
        f"{q[0]['seeds']} seeds per budget. *Precision* is the share of shown entities (seed excluded) in the seed's "
        "community; *recall* the share of its 49 other members shown. Every method is rendered in the same compact "
        "text form except the two Cypher rows, which are what a model gets from a neighbourhood query returned as JSON.",
        "",
        "| budget | method | precision | recall | nodes shown | tokens (mean) | p50 |",
        "|---:|---|---:|---:|---:|---:|---:|",
    ]
    for r in q:
        out.append(
            f"| {r['budget']:,} | {r['method']} | {r['precision']:.3f} | {r['recall']:.3f} | {r['shown']:,.1f} | "
            f"{fmt_int(r['tokens_mean'])} | {r['ms_p50']:.2f} ms |"
        )
    out += [
        "",
        "- At 4,000 tokens about 90 nodes fit but the community has only 49 other members, so precision there is capped "
        "near 0.55; recall is what to read.",
        "- \"no hub damping\" pushes PageRank mass through the hubs (`max_fanout` unlimited): about the same answer, "
        "15–25× slower, because each push through a hub touches its tens of thousands of neighbours.",
        "- The Cypher 1-hop answer shows about as many relevant nodes as `retrieve` does in 500 tokens, for ~10× the "
        "tokens, and cannot be asked for more; 2 hops is millions of tokens.",
        "",
    ]

if s:
    db = s[0]
    meta = next((r for r in s if "gib" in r), None)
    out += [
        "## Cost on a 1 GiB database",
        "",
        f"`scale-gen --size 1GiB --paged`: {meta['nodes']:,} nodes, {meta['edges']:,} edges, {meta['gib']:.2f} GiB on disk "
        f"(16 relationship regimes, power-law hubs, long text, lists). Page cache {meta['cache_mb']} MiB; the process ran "
        "under a 2 GiB memory cap. *cold*: the file evicted from the OS page cache first; *warm*: the run after. "
        "*misses*: glider page-cache misses per call. Seeds are random nodes; paths join random pairs.",
        "",
        "| op | cache | p50 | p95 | misses p50 | notes |",
        "|---|---|---:|---:|---:|---|",
    ]
    for r in s:
        if r["op"] == "peak_rss":
            continue
        notes = []
        for k, label in [("tokens_p50", "tokens p50"), ("shown_p50", "nodes shown p50"), ("reached_p50", "nodes touched p50"),
                         ("found", "paths found"), ("hops_p50", "hops p50"), ("tokens", "tokens"), ("postings_p50", "postings read p50"),
                         ("result", "")]:
            if k in r:
                v = r[k]
                notes.append(f"{label} {fmt_int(v)}" if isinstance(v, (int, float)) else str(v))
        out.append(f"| {r['op']} | {r['cache']} | {r['ms_p50']:.2f} ms | {r['ms_p95']:.2f} ms | {fmt_int(r['misses_p50'])} | {'; '.join(notes)} |")
    for r in s:
        if r["op"] == "peak_rss":
            out.append(f"\nPeak RSS ({r['cache']}): {r['peak_rss_mb']:,} MB.")
    out += [
        "",
        "- `retrieve` touches a few thousand nodes whatever the graph's size (local push), so its cost is set by page "
        "reads, not by the 1.2M nodes; cold, most of the time is ~200 page misses.",
        "- The generator's text comes from a vocabulary of ~50 words, so every query term is in most documents: the worst "
        "case for an inverted index. Each term's postings are read up to 50,000.",
        "- The index is maintained by the write hook in the writing transaction; a `CREATE` of an indexed node stays well "
        "under a millisecond.",
        "",
    ]

open(OUT, "w").write("\n".join(out) + "\n")
print("wrote", OUT)
